      "$\\text{Ethyl bromide } [\\text{CH}_3\\text{CH}_2-\\text{Br}]$",
      "$\\text{Methyl bromide } [\\text{CH}_3-\\text{Br}]$",
      "$\\text{tert-Butyl bromide } [(\\text{CH}_3)_3\\text{C}-\\text{Br}]$"
